extra_css:
/* Lumen Circuit surfaces: panels are slabs of black glass on the grid, edged with a thin line of light that runs along the top
   (a scan that travels the edge), cut corners like circuit traces, and a faint floor reflection. Scoped to the theme's own surfaces. */
html[data-atmo="lumen"] .card, html[data-atmo="lumen"] .panel, html[data-atmo="lumen"] .gx-card {
  background: linear-gradient(180deg, rgba(14,22,40,.78), rgba(3,5,11,.9)), repeating-linear-gradient(90deg, rgba(63,224,255,.035) 0 1px, transparent 1px 28px);
  backdrop-filter: blur(12px) saturate(150%); -webkit-backdrop-filter: blur(12px) saturate(150%);
  box-shadow: inset 0 1px 0 rgba(63,224,255,.55), inset 0 0 0 1px rgba(63,224,255,.14), 0 0 22px rgba(63,224,255,.10), 0 22px 50px rgba(0,0,0,.7);
  clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 14px 100%, 0 calc(100% - 14px));
  transition: box-shadow .3s, transform .3s cubic-bezier(.2,1.2,.4,1); }
html[data-atmo="lumen"] .card:hover, html[data-atmo="lumen"] .gx-card:hover {
  transform: translateY(-2px); box-shadow: inset 0 1px 0 rgba(255,190,90,.8), inset 0 0 0 1px rgba(63,224,255,.3), 0 0 30px rgba(63,224,255,.22), 0 26px 60px rgba(0,0,0,.75); }
html[data-atmo="lumen"] h1, html[data-atmo="lumen"] h2 { letter-spacing: .08em; text-shadow: 0 0 12px rgba(63,224,255,.55), 0 0 2px rgba(220,250,255,.9); }
@media (prefers-reduced-motion: no-preference) {
  html[data-atmo="lumen"] .card::after, html[data-atmo="lumen"] .gx-card::after { content: ""; position: absolute; left: 0; top: 0; height: 1px; width: 30%; pointer-events: none;
    background: linear-gradient(90deg, transparent, #fff, #3fe0ff, transparent); animation: lumen-scan 3.6s linear infinite; }
}
@keyframes lumen-scan { from { transform: translateX(-100%); } to { transform: translateX(400%); } }

